69	function usePlanContent(planPath: string, config: Config): PlanContentState {
70	  const [version, setVersion] = useState(0);
71	  const [state, setState] = useState<Omit<PlanContentState, 'refresh'>>({
72	    status: PlanStatus.Loading,
73	  });
74	
75	  const refresh = useCallback(() => {
76	    setVersion((v) => v + 1);
77	  }, []);
78	
79	  useEffect(() => {
80	    let ignore = false;
81	    setState({ status: PlanStatus.Loading });
82	
83	    const load = async () => {
84	      try {
85	        const pathError = await validatePlanPath(
86	          planPath,
87	          config.storage.getPlansDir(),
88	          config.getProjectRoot(),
89	        );
90	        if (ignore) return;
91	        if (pathError) {
92	          setState({ status: PlanStatus.Error, error: pathError });
93	          return;
94	        }
95	
96	        const contentError = await validatePlanContent(planPath);
97	        if (ignore) return;
98	        if (contentError) {
99	          setState({ status: PlanStatus.Error, error: contentError });
100	          return;
101	        }
102	
103	        const result = await processSingleFileContent(
104	          planPath,
105	          config.storage.getPlansDir(),
106	          config.getFileSystemService(),
107	        );
108	
109	        if (ignore) return;
110	
111	        if (result.error) {
112	          setState({ status: PlanStatus.Error, error: result.error });
113	          return;
114	        }
115	
116	        if (typeof result.llmContent !== 'string') {
117	          setState({
118	            status: PlanStatus.Error,
119	            error: 'Plan file format not supported (binary or image).',
120	          });
121	          return;
122	        }
123	
124	        const content = result.llmContent;
125	        if (!content) {
126	          setState({ status: PlanStatus.Error, error: 'Plan file is empty.' });
127	          return;
128	        }
129	        setState({ status: PlanStatus.Loaded, content });
130	      } catch (err: unknown) {
131	        if (ignore) return;
132	        const errorMessage = err instanceof Error ? err.message : String(err);
133	        setState({ status: PlanStatus.Error, error: errorMessage });
134	      }
135	    };
136	
137	    void load();
138	
139	    return () => {
140	      ignore = true;
141	    };
142	  }, [planPath, config, version]);
143	
144	  return { ...state, refresh };
145	}
