  const realPlansDir = resolveToRealPath(plansDir);

  if (!isSubpath(realPlansDir, realPath)) {
    throw new Error(
      PlanErrorMessages.PATH_ACCESS_DENIED(trimmedPath, plansDir),
    );
  }

  return resolvedPath;
}

